import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

interface BankObserver {}
final class Account {
    private final String id;
    Account(String id) { this.id = id; }
    String getId() { return id; }
}

public class BankingEngine {
    private final Map<String, Account> accounts = new HashMap<>();
    private final List<BankObserver> observers = new ArrayList<>();

    public void registerObserver(BankObserver observer) {
        observers.add(observer);
    }

    public void addAccount(Account account) {
        accounts.put(account.getId(), account);
    }

    public Account getAccount(String id) {
        return accounts.get(id);
    }
}

exercise.testHarness:
BankingEngine engine = new BankingEngine();
Account account = new Account("ACC-1");
engine.addAccount(account);
check("account-repository", "Banking facade indexes and retrieves accounts", engine.getAccount("ACC-1") == account, "same Account instance", engine.getAccount("ACC-1"), "Store accounts under their stable identifier.", "addAccount");
BankObserver observer = new BankObserver() {};
engine.registerObserver(observer);
Object observers = field(engine, "observers");
check("observer-registration", "Banking facade retains registered observers", observers instanceof java.util.List && ((java.util.List<?>) observers).size() == 1, "1 observer", observers, "Add the observer to the private list.", "registerObserver");

